"// service-worker.js - Meeting Shadow Agent Background Worker
const OFFSCREEN_DOCUMENT_PATH = 'offscreen.html';

async function hasOffscreenDocument() {
  if (chrome.offscreen && chrome.offscreen.hasDocument) {
    return await chrome.offscreen.hasDocument();
  }
  const matchedClients = await clients.matchAll();
  for (const client of matchedClients) {
    if (client.url.includes(OFFSCREEN_DOCUMENT_PATH)) {
      return true;
    }
  }
  return false;
}

async function setupOffscreenDocument() {
  if (await hasOffscreenDocument()) {
    return;
  }
  if (chrome.offscreen) {
    try {
      await chrome.offscreen.createDocument({
        url: OFFSCREEN_DOCUMENT_PATH,
        reasons: ['USER_MEDIA', 'AUDIO_PLAYBACK'],
        justification: 'Continuously capture tab/mic audio and transcribe in background when popup is closed',
      });
    } catch (e) {
      console.error("Failed to create offscreen document:", e);
    }
  }
}

